<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();ensure_feedback_schema();
$adminPage='feedback';$adminTitle='Feedback de vendedores';$adminSubtitle='Lee, responde, califica y comparte ideas de la comunidad.';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 try{
  if($action==='settings'){
   $enabled=!empty($_POST['feedback_public_enabled'])?'1':'0';
   db()->prepare("INSERT INTO settings(`key`,value) VALUES('feedback_public_enabled',?) ON DUPLICATE KEY UPDATE value=VALUES(value)")->execute([$enabled]);
   flash('success','Configuración pública actualizada.');redirect('feedback.php');
  }
  $q=db()->prepare('SELECT * FROM feedback_threads WHERE id=?');$q->execute([$id]);$thread=$q->fetch();if(!$thread)throw new RuntimeException('Feedback no encontrado.');
  if($action==='reply'){
   $body=trim((string)($_POST['body']??''));if(mb_strlen($body)<2||mb_strlen($body)>5000)throw new RuntimeException('La respuesta debe tener entre 2 y 5.000 caracteres.');
   db()->prepare('INSERT INTO feedback_messages(thread_id,user_id,body) VALUES(?,?,?)')->execute([$id,(int)user()['id'],$body]);
   db()->prepare("UPDATE feedback_threads SET status='answered',admin_read=1,seller_read=0,assigned_admin_id=?,updated_at=NOW() WHERE id=?")->execute([(int)user()['id'],$id]);
   flash('success','Respuesta enviada al vendedor.');redirect('feedback.php?id='.$id);
  }
  if($action==='update'){
   $status=(string)($_POST['status']??'open');if(!in_array($status,['open','answered','closed'],true))$status='open';
   $rating=(int)($_POST['admin_rating']??0);if($rating<0||$rating>5)$rating=0;
   $public=!empty($_POST['is_public'])?1:0;
   db()->prepare('UPDATE feedback_threads SET status=?,admin_rating=?,is_public=?,admin_read=1,assigned_admin_id=?,updated_at=NOW() WHERE id=?')->execute([$status,$rating?:null,$public,(int)user()['id'],$id]);
   flash('success','Feedback actualizado.');redirect('feedback.php?id='.$id);
  }
  if($action==='mark_read'){db()->prepare('UPDATE feedback_threads SET admin_read=1 WHERE id=?')->execute([$id]);flash('success','Marcado como leído.');redirect('feedback.php');}
 }catch(Throwable $e){flash('error',$e->getMessage());redirect('feedback.php'.($id?'?id='.$id:''));}
}
$filter=$_GET['filter']??'all';$where='1=1';if($filter==='unread')$where='ft.admin_read=0';elseif(in_array($filter,['open','answered','closed'],true))$where="ft.status='".$filter."'";elseif($filter==='public')$where='ft.is_public=1';
$q=db()->query("SELECT ft.*,u.username,u.email,p.display_name,p.business_local,(SELECT COUNT(*) FROM feedback_messages fm WHERE fm.thread_id=ft.id) message_count FROM feedback_threads ft JOIN users u ON u.id=ft.seller_id LEFT JOIN profiles p ON p.user_id=u.id WHERE $where ORDER BY ft.admin_read ASC,COALESCE(ft.updated_at,ft.created_at) DESC");$threads=$q->fetchAll();
$id=(int)($_GET['id']??0);$thread=null;$messages=[];
if($id){$q=db()->prepare('SELECT ft.*,u.username,u.email,p.display_name,p.avatar,p.business_local FROM feedback_threads ft JOIN users u ON u.id=ft.seller_id LEFT JOIN profiles p ON p.user_id=u.id WHERE ft.id=?');$q->execute([$id]);$thread=$q->fetch();if($thread){db()->prepare('UPDATE feedback_threads SET admin_read=1 WHERE id=?')->execute([$id]);$q=db()->prepare('SELECT fm.*,u.role,u.username,p.display_name,p.avatar FROM feedback_messages fm JOIN users u ON u.id=fm.user_id LEFT JOIN profiles p ON p.user_id=u.id WHERE fm.thread_id=? ORDER BY fm.created_at');$q->execute([$id]);$messages=$q->fetchAll();}}
$stats=db()->query("SELECT COUNT(*) total,SUM(admin_read=0) unread,SUM(status='open') open_count,SUM(status='answered') answered_count,SUM(is_public=1) public_count FROM feedback_threads")->fetch();
require __DIR__.'/partials/header.php';?>
<link rel="stylesheet" href="<?=url('assets/css/feedback.css')?>">
<div class="admin-grid cols-4"><article class="metric-card"><div class="metric-icon">💬</div><div><strong><?=(int)$stats['total']?></strong><small>Total feedbacks</small></div></article><article class="metric-card warning"><div class="metric-icon">🔔</div><div><strong><?=(int)$stats['unread']?></strong><small>Sin leer</small></div></article><article class="metric-card info"><div class="metric-icon">🛠️</div><div><strong><?=(int)$stats['open_count']?></strong><small>Abiertos</small></div></article><article class="metric-card"><div class="metric-icon">🌐</div><div><strong><?=(int)$stats['public_count']?></strong><small>Públicos</small></div></article></div>
<section class="panel-card"><div class="panel-head"><div><h2>Visibilidad comunitaria</h2><p>Permite mostrar en una página pública los feedbacks que marques como públicos.</p></div><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="settings"><label class="switch-row"><input type="checkbox" name="feedback_public_enabled" value="1" <?=setting('feedback_public_enabled','0')==='1'?'checked':''?>> Habilitar comunidad pública</label><button class="admin-btn small">Guardar</button></form></div></section>
<div class="admin-feedback-layout">
<section class="panel-card feedback-inbox"><div class="panel-head"><div><h2>Bandeja de feedback</h2><p>Ordenada con los mensajes sin leer primero.</p></div></div><div class="feedback-filters"><a class="<?=$filter==='all'?'active':''?>" href="feedback.php">Todos</a><a class="<?=$filter==='unread'?'active':''?>" href="?filter=unread">Sin leer</a><a class="<?=$filter==='open'?'active':''?>" href="?filter=open">Abiertos</a><a class="<?=$filter==='answered'?'active':''?>" href="?filter=answered">Respondidos</a><a class="<?=$filter==='closed'?'active':''?>" href="?filter=closed">Cerrados</a><a class="<?=$filter==='public'?'active':''?>" href="?filter=public">Públicos</a></div><div class="admin-feedback-list"><?php if(!$threads):?><p class="empty-note">No hay feedbacks para este filtro.</p><?php endif;?><?php foreach($threads as $t):?><a href="feedback.php?id=<?=$t['id']?>&filter=<?=e($filter)?>" class="<?=!$t['admin_read']?'unread':''?> <?=$id===$t['id']?'active':''?>"><div><span><?=feedback_category_label($t['category'])?></span><?php if(!$t['admin_read']):?><em>Nuevo</em><?php endif;?></div><b><?=e($t['subject'])?></b><small><?=e($t['display_name']?:$t['username'])?> · <?=feedback_status_label($t['status'])?> · <?=$t['message_count']?> mensajes</small><footer><?=feedback_stars((int)($t['seller_rating']??0))?><time><?=date('d/m/Y',strtotime($t['created_at']))?></time></footer></a><?php endforeach;?></div></section>
<section class="panel-card feedback-admin-detail"><?php if(!$thread):?><div class="feedback-empty-detail"><span>📨</span><h2>Selecciona un feedback</h2><p>Podrás leer la conversación, responder, asignar estrellas y decidir si será visible para la comunidad.</p></div><?php else:?><div class="feedback-admin-head"><div><span><?=feedback_category_label($thread['category'])?></span><h2><?=e($thread['subject'])?></h2><p><?=e($thread['display_name']?:$thread['username'])?> · <?=e($thread['business_local']?:'Vendedor')?> · <?=e($thread['email'])?></p></div><span class="feedback-status <?=$thread['status']?>"><?=feedback_status_label($thread['status'])?></span></div><div class="feedback-messages admin-view"><?php foreach($messages as $msg):$a=$msg['role']==='admin';?><article class="feedback-message <?=$a?'admin':'seller'?>"><img src="<?=url($msg['avatar']?:'assets/img-avatar.svg')?>"><div><header><b><?=e($msg['display_name']?:$msg['username'])?></b><span><?=$a?'🛡️ Administración':'🏪 Vendedor'?></span><time><?=date('d/m/Y H:i',strtotime($msg['created_at']))?></time></header><p><?=nl2br(e($msg['body']))?></p></div></article><?php endforeach;?></div><form method="post" class="feedback-reply admin-reply"><?=csrf_field()?><input type="hidden" name="action" value="reply"><input type="hidden" name="id" value="<?=$thread['id']?>"><label>Responder al vendedor<textarea name="body" rows="5" maxlength="5000" required placeholder="Explica la decisión, avance o solución..."></textarea></label><button class="admin-btn">📨 Responder</button></form><form method="post" class="feedback-admin-controls"><?=csrf_field()?><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$thread['id']?>"><div class="form-grid"><label>Estado<select name="status"><option value="open" <?=$thread['status']==='open'?'selected':''?>>Abierto</option><option value="answered" <?=$thread['status']==='answered'?'selected':''?>>Respondido</option><option value="closed" <?=$thread['status']==='closed'?'selected':''?>>Cerrado</option></select></label><label>Calidad del aporte<?=feedback_stars((int)($thread['admin_rating']??0),true,'admin_rating')?></label></div><label class="check-card"><input type="checkbox" name="is_public" value="1" <?=$thread['is_public']?'checked':''?>><span><b>Publicar en la comunidad</b><small>Otros vendedores podrán ver el asunto, estado y valoración.</small></span></label><button class="admin-btn success">💾 Guardar seguimiento</button></form><?php endif;?></section></div>
<?php require __DIR__.'/partials/footer.php';?>
